fn solve(input: Vec<i8>) -> Vec<i8> {
    // Check if the input has fewer than three elements
    if input.len() < 3 {
        return Vec::new(); // Return an empty list
    }

    // Extract the first three elements
    let capacity = input[0];
    let current = input[1];
    let incoming = input[2];

    // Calculate the leftover amount
    let available_space = capacity - current;
    let leftover = incoming - available_space;

    // Clamp the leftover to the signed 8-bit range
    let clamped_leftover = if leftover > 127 {
        127
    } else if leftover < -128 {
        -128
    } else {
        leftover
    };

    // Return the result as a vector containing the clamped leftover
    vec![clamped_leftover]
}